cat >> tests/test_cli.py <<'EOF'


def _render_done(capsys, data: dict) -> tuple[str, str]:
    from pharma_agent.application.progress import EventType, ProgressEvent

    cli._render(ProgressEvent(type=EventType.DONE, data=data), [])
    captured = capsys.readouterr()
    return captured.out, captured.err


def test_render_done_reports_unsaved_turn_on_stderr(capsys) -> None:
    out, err = _render_done(
        capsys, {"status": "completed", "message_id": None, "persisted": False}
    )
    assert err == "!! Không lưu được lượt hội thoại này.\n"
    assert out == ""


def test_render_done_is_silent_when_saved_or_unknown(capsys) -> None:
    assert _render_done(
        capsys, {"status": "completed", "message_id": "m1", "persisted": True}
    ) == ("", "")
    assert _render_done(capsys, {"status": "completed"}) == ("", "")
EOF
uv run pytest -q tests/test_cli.py 2>&1 | tail -3

